    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int next(void) {
    static int s = 10;
    int t = 10;
    s = s + 3;
    t = t + 3;
    return s + t;
}
int main(void) {
    next();
    next();
    printf("%d", next());
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int pile(int v) {
    static int sum;
    sum = sum + v;
    return sum;
}
int main(void) {
    int a = pile(4);
    int b = pile(3);
    printf("%d %d", a, b);
    return 0;
}

다음 Java 프로그램의 실행 결과는?

[코드]
class Main {
    static void p(String s) {
        System.out.print(s);
    }
    public static void main(String[] a) {
        int stock = 0;
        try {
            p("1");
            if (stock == 0)
                throw new Exception("7");
            p("2");
        } catch (Exception e) {
            p(e.getMessage());
            p("3");
        } finally {
            p("4");
        }
        p("5");
    }
}

다음 Java 프로그램의 실행 결과는? (단, IllegalStateException과 ArithmeticException은 서로 상속 관계가 없는 예외 클래스이다)

[코드]
class Main {
    static void p(String s) {
        System.out.print(s);
    }
    public static void main(String[] a) {
        int key = 1;
        try {
            p("P");
            if (key == 1)
                throw new IllegalStateException("Q");
            p("K");
        } catch (ArithmeticException e) {
            p("R");
        } catch (IllegalStateException e) {
            p("S");
        } finally {
            p("T");
        }
        p("U");
    }
}

