int g;
int twice(int g) {
    g = g * 2;
    return g;
}
int main(void) {
    int r = twice(7);
    g = g + 1;
    printf("%d %d", r, g);
    return 0;
}

다음 Java 프로그램의 실행 결과는?

[코드]
class Main {
    static int f(int n) {
        int r = 0;
        try {
            if (n < 0)
                throw new Exception("neg");
            r = r + 1;
        } catch (Exception e) {
            r = r + 10;
        } finally {
            r = r + 100;
        }
        return r;
    }
    public static void main(String[] a) {
        System.out.print(f(4) + " " + f(-4));
    }
}

다음 Java 프로그램의 실행 결과는?

[코드]
class Main {
    public static void main(String[] a) {
        int n = 0;
        try {
            n = n + 1;
            if (n == 1)
                throw new Exception("x");
            n = n + 10;
        } catch (Exception e) {
            n = n + 100;
        }
        try {
            n = n + 1000;
        } catch (Exception e) {
            n = n + 5;
        } finally {
            n = n * 2;
        }
        System.out.print(n);
    }
}
